from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message


class PesanTolak(Component):
    display_name = "Pesan Tolak"
    description = "Pesan penolakan berbahasa Indonesia untuk jalur Fail."

    inputs = [
        MessageTextInput(
            name="alasan",
            display_name="Alasan (diabaikan)",
            info="Dihubungkan ke Fail Guardrails hanya sebagai pemicu.",
        ),
    ]
    outputs = [
        Output(display_name="Pesan", name="pesan", method="buat_pesan"),
    ]

    def buat_pesan(self) -> Message:
        return Message(
            text=(
                "Maaf, permintaan ini tidak dapat diproses. Saya hanya bisa "
                "membantu pertanyaan seputar kondisi jantung pasien (detak "
                "jantung, SpO2, dan status pengukuran). Silakan ubah "
                "pertanyaan Anda lalu coba lagi."
            )
        )
